  this.JX = new $c_Lelysion_lesson_Texts("Begin", "\u041d\u0430\u0447\u0430\u0442\u044c", "\u041f\u043e\u0447\u0430\u0442\u0438", "Zacznij");
  this.K8 = new $c_Lelysion_lesson_Texts("Lessons", "\u0423\u0440\u043e\u043a\u0438", "\u0423\u0440\u043e\u043a\u0438", "Lekcje");
  this.Bq = new $c_Lelysion_lesson_Texts("All lessons", "\u0412\u0441\u0435 \u0443\u0440\u043e\u043a\u0438", "\u0423\u0441\u0456 \u0443\u0440\u043e\u043a\u0438", "Wszystkie lekcje");
  this.Kf = new $c_Lelysion_lesson_Texts("Questions every tradition has answered \u2014 Greek and Indian, Chinese and Christian, old and new. Answer first; then read the thinkers in their own words, and see where you stand.", "\u0412\u043e\u043f\u0440\u043e\u0441\u044b, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u043b\u0430 \u043a\u0430\u0436\u0434\u0430\u044f \u0442\u0440\u0430\u0434\u0438\u0446\u0438\u044f, \u2014 \u0433\u0440\u0435\u0447\u0435\u0441\u043a\u0430\u044f \u0438 \u0438\u043d\u0434\u0438\u0439\u0441\u043a\u0430\u044f, \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0430\u044f \u0438 \u0445\u0440\u0438\u0441\u0442\u0438\u0430\u043d\u0441\u043a\u0430\u044f, \u0434\u0440\u0435\u0432\u043d\u044f\u044f \u0438 \u043d\u043e\u0432\u0430\u044f. \u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043e\u0442\u0432\u0435\u0442\u044c\u0442\u0435 \u0441\u0430\u043c\u0438; \u043f\u043e\u0442\u043e\u043c \u043f\u0440\u043e\u0447\u0442\u0438\u0442\u0435 \u043c\u044b\u0441\u043b\u0438\u0442\u0435\u043b\u0435\u0439 \u0438\u0445 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c\u0438 \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u0438 \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435, \u0433\u0434\u0435 \u0432\u044b.", "\u041f\u0438\u0442\u0430\u043d\u043d\u044f, \u043d\u0430 \u044f\u043a\u0456 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u043b\u0430 \u043a\u043e\u0436\u043d\u0430 \u0442\u0440\u0430\u0434\u0438\u0446\u0456\u044f, \u2014 \u0433\u0440\u0435\u0446\u044c\u043a\u0430 \u0439 \u0456\u043d\u0434\u0456\u0439\u0441\u044c\u043a\u0430, \u043a\u0438\u0442\u0430\u0439\u0441\u044c\u043a\u0430 \u0439 \u0445\u0440\u0438\u0441\u0442\u0438\u044f\u043d\u0441\u044c\u043a\u0430, \u0434\u0430\u0432\u043d\u044f \u0456 \u043d\u043e\u0432\u0430. \u0421\u043f\u0435\u0440\u0448\u0443 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u0439\u0442\u0435 \u0441\u0430\u043c\u0456; \u043f\u043e\u0442\u0456\u043c \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u043c\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u0456\u0432 \u0457\u0445\u043d\u0456\u043c\u0438 \u0432\u043b\u0430\u0441\u043d\u0438\u043c\u0438 \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u0456 \u043f\u043e\u0434\u0438\u0432\u0456\u0442\u044c\u0441\u044f, \u0434\u0435 \u0432\u0438.", "Pytania, na kt\u00f3re odpowiada\u0142a ka\u017cda tradycja \u2014 grecka i indyjska, chi\u0144ska i chrze\u015bcija\u0144ska, dawna i nowa. Najpierw odpowiedz sam; potem przeczytaj my\u015blicieli ich w\u0142asnymi s\u0142owami i zobacz, gdzie stoisz.");
  this.Bs = new $c_Lelysion_lesson_Texts("Next", "\u0414\u0430\u043b\u044c\u0448\u0435", "\u0414\u0430\u043b\u0456", "Dalej");
  this.JV = new $c_Lelysion_lesson_Texts("Four languages \u00b7 about fifteen minutes a lesson \u00b7 your answers stay on this device", "\u0427\u0435\u0442\u044b\u0440\u0435 \u044f\u0437\u044b\u043a\u0430 \u00b7 \u043e\u043a\u043e\u043b\u043e \u043f\u044f\u0442\u043d\u0430\u0434\u0446\u0430\u0442\u0438 \u043c\u0438\u043d\u0443\u0442 \u043d\u0430 \u0443\u0440\u043e\u043a \u00b7 \u0432\u0430\u0448\u0438 \u043e\u0442\u0432\u0435\u0442\u044b \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u043d\u0430 \u044d\u0442\u043e\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435", "\u0427\u043e\u0442\u0438\u0440\u0438 \u043c\u043e\u0432\u0438 \u00b7 \u0431\u043b\u0438\u0437\u044c\u043a\u043e \u043f'\u044f\u0442\u043d\u0430\u0434\u0446\u044f\u0442\u0438 \u0445\u0432\u0438\u043b\u0438\u043d \u043d\u0430 \u0443\u0440\u043e\u043a \u00b7 \u0432\u0430\u0448\u0456 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0456 \u0437\u0430\u043b\u0438\u0448\u0430\u044e\u0442\u044c\u0441\u044f \u043d\u0430 \u0446\u044c\u043e\u043c\u0443 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457", "Cztery j\u0119zyki \u00b7 oko\u0142o pi\u0119tnastu minut na lekcj\u0119 \u00b7 twoje odpowiedzi zostaj\u0105 na tym urz\u0105dzeniu");
  this.K5 = new $c_Lelysion_lesson_Texts("What happened", "\u0427\u0442\u043e \u0431\u044b\u043b\u043e \u043d\u0430 \u0441\u0430\u043c\u043e\u043c \u0434\u0435\u043b\u0435", "\u0429\u043e \u0431\u0443\u043b\u043e \u043d\u0430\u0441\u043f\u0440\u0430\u0432\u0434\u0456", "Co wydarzy\u0142o si\u0119 naprawd\u0119");
  this.K1 = new $c_Lelysion_lesson_Texts("Historical context", "\u0418\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442", "\u0406\u0441\u0442\u043e\u0440\u0438\u0447\u043d\u0438\u0439 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442", "Kontekst historyczny");
  this.Kh = new $c_Lelysion_lesson_Texts("Your answer", "\u0412\u0430\u0448 \u043e\u0442\u0432\u0435\u0442", "\u0412\u0430\u0448\u0430 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u044c", "Twoja odpowied\u017a");
  this.K7 = new $c_Lelysion_lesson_Texts("Keep my answer", "\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u043e\u0442\u0432\u0435\u0442", "\u0417\u0431\u0435\u0440\u0435\u0433\u0442\u0438 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u044c", "Zachowaj odpowied\u017a");
  this.Ke = new $c_Lelysion_lesson_Texts("Skip", "\u041f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c", "\u041f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u0438", "Pomi\u0144");
  this.K2 = new $c_Lelysion_lesson_Texts("The lesson is done", "\u0423\u0440\u043e\u043a \u043f\u0440\u043e\u0439\u0434\u0435\u043d", "\u0423\u0440\u043e\u043a \u043f\u0440\u043e\u0439\u0434\u0435\u043d\u043e", "Lekcja uko\u0144czona");
  this.JW = new $c_Lelysion_lesson_Texts("Before you read anyone", "\u0414\u043e \u0447\u0442\u0435\u043d\u0438\u044f", "\u0414\u043e \u0447\u0438\u0442\u0430\u043d\u043d\u044f", "Zanim przeczyta\u0142e\u015b kogokolwiek");
  this.Kc = new $c_Lelysion_lesson_Texts("Now", "\u0421\u0435\u0439\u0447\u0430\u0441", "\u0422\u0435\u043f\u0435\u0440", "Teraz");
  this.Kd = new $c_Lelysion_lesson_Texts("You answered the same \u2014 the thinkers did not change your mind, or they confirmed it.", "\u0412\u044b \u043e\u0442\u0432\u0435\u0442\u0438\u043b\u0438 \u0442\u0430\u043a \u0436\u0435 \u2014 \u043c\u044b\u0441\u043b\u0438\u0442\u0435\u043b\u0438 \u043d\u0435 \u043f\u0435\u0440\u0435\u0443\u0431\u0435\u0434\u0438\u043b\u0438 \u0432\u0430\u0441 \u0438\u043b\u0438 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0438 \u0432\u0430\u0448\u0443 \u043c\u044b\u0441\u043b\u044c.", "\u0412\u0438 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u043b\u0438 \u0442\u0430\u043a \u0441\u0430\u043c\u043e \u2014 \u043c\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u0456 \u043d\u0435 \u043f\u0435\u0440\u0435\u043a\u043e\u043d\u0430\u043b\u0438 \u0432\u0430\u0441 \u0430\u0431\u043e \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0438 \u0432\u0430\u0448\u0443 \u0434\u0443\u043c\u043a\u0443.", "Odpowiedzia\u0142e\u015b tak samo \u2014 my\u015bliciele ci\u0119 nie przekonali albo potwierdzili twoje zdanie.");
  this.JZ = new $c_Lelysion_lesson_Texts("Your answer changed.", "\u0412\u0430\u0448 \u043e\u0442\u0432\u0435\u0442 \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0441\u044f.", "\u0412\u0430\u0448\u0430 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u044c \u0437\u043c\u0456\u043d\u0438\u043b\u0430\u0441\u044f.", "Twoja odpowied\u017a si\u0119 zmieni\u0142a.");
  this.Ki = new $c_Lelysion_lesson_Texts("Your thought", "\u0412\u0430\u0448\u0430 \u043c\u044b\u0441\u043b\u044c", "\u0412\u0430\u0448\u0430 \u0434\u0443\u043c\u043a\u0430", "Twoja my\u015bl");
  this.K0 = new $c_Lelysion_lesson_Texts("Next: what is justice? do we have free will? why do republics fall? \u2014 and arguing your answers with Socrates.", "\u0414\u0430\u043b\u044c\u0448\u0435: \u0447\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e\u0441\u0442\u044c? \u0435\u0441\u0442\u044c \u043b\u0438 \u0443 \u043d\u0430\u0441 \u0441\u0432\u043e\u0431\u043e\u0434\u0430 \u0432\u043e\u043b\u0438? \u043f\u043e\u0447\u0435\u043c\u0443 \u043f\u0430\u0434\u0430\u044e\u0442 \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438? \u2014 \u0438 \u0441\u043f\u043e\u0440 \u043e \u0432\u0430\u0448\u0438\u0445 \u043e\u0442\u0432\u0435\u0442\u0430\u0445 \u0441 \u0421\u043e\u043a\u0440\u0430\u0442\u043e\u043c.", "\u0414\u0430\u043b\u0456: \u0449\u043e \u0442\u0430\u043a\u0435 \u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u0456\u0441\u0442\u044c? \u0447\u0438 \u043c\u0430\u0454\u043c\u043e \u043c\u0438 \u0441\u0432\u043e\u0431\u043e\u0434\u0443 \u0432\u043e\u043b\u0456? \u0447\u043e\u043c\u0443 \u043f\u0430\u0434\u0430\u044e\u0442\u044c \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0456\u043a\u0438? \u2014 \u0456 \u0441\u0443\u043f\u0435\u0440\u0435\u0447\u043a\u0430 \u043f\u0440\u043e \u0432\u0430\u0448\u0456 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0456 \u0456\u0437 \u0421\u043e\u043a\u0440\u0430\u0442\u043e\u043c.", "Dalej: czym jest sprawiedliwo\u015b\u0107? czy mamy woln\u0105 wol\u0119? dlaczego upadaj\u0105 republiki? \u2014 i sp\u00f3r o twoje odpowiedzi z Sokratesem.");
  this.K6 = new $c_Lelysion_lesson_Texts("The judge is reading your answer\u2026", "\u0421\u0443\u0434\u044c\u044f \u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u0430\u0448 \u043e\u0442\u0432\u0435\u0442\u2026", "\u0421\u0443\u0434\u0434\u044f \u0447\u0438\u0442\u0430\u0454 \u0432\u0430\u0448\u0443 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u044c\u2026", "S\u0119dzia czyta twoj\u0105 odpowied\u017a\u2026");
  this.Br = new $c_Lelysion_lesson_Texts("The judge", "\u0421\u0443\u0434\u044c\u044f", "\u0421\u0443\u0434\u0434\u044f", "S\u0119dzia");
  this.K9 = new $c_Lelysion_lesson_Texts("Nearest to you", "\u0411\u043b\u0438\u0436\u0435 \u0432\u0441\u0435\u0433\u043e \u043a \u0432\u0430\u043c", "\u041d\u0430\u0439\u0431\u043b\u0438\u0436\u0447\u0435 \u0434\u043e \u0432\u0430\u0441", "Najbli\u017cej ciebie");
